import{_ as l,a0 as r,w as s,s as u,ao as p,I as n,x as a,a1 as e,A as o}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const M=JSON.parse('{"title":"GTK4 和 Libadwaita 讓 GNOME 43 的文件管理器看起來很出色 | LCTT x X-CMD","titleTemplate":false,"description":"GTK4 和 Libadwaita 讓 GNOME 43 的文件管理器看起來很出色 | LCTT (202204) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"GTK4 和 Libadwaita 讓 GNOME 43 的文件管理器看起來很出色 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"GTK4 和 Libadwaita 讓 GNOME 43 的文件管理器看起來很出色 | LCTT (202204) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202204/20220303 Nautilus File Manager Looks Amazing with GTK4 and Libadwaita - A Deep Dive","title":"GTK4 和 Libadwaita 讓 GNOME 43 的文件管理器看起來很出色","tag":"202204","desc":""},"relativePath":"202204/20220303 Nautilus File Manager Looks Amazing with GTK4 and Libadwaita - A Deep Dive.md","filePath":"[post].md"}'),d={name:"202204/20220303 Nautilus File Manager Looks Amazing with GTK4 and Libadwaita - A Deep Dive.md"};function m(b,t,w,g,f,T){const i=r("Link");return s(),u("div",null,[t[25]||(t[25]=p('<h1 id="gtk4-和-libadwaita-讓-gnome-43-的文件管理器看起來很出色" tabindex="-1">GTK4 和 Libadwaita 讓 GNOME 43 的文件管理器看起來很出色 <a class="header-anchor" href="#gtk4-和-libadwaita-讓-gnome-43-的文件管理器看起來很出色" aria-label="Permalink to “GTK4 和 Libadwaita 讓 GNOME 43 的文件管理器看起來很出色”">​</a></h1><p><img src="https://img.linux.net.cn/data/attachment/album/202204/07/163919x7t2hbblzmthmjfk.jpg" alt=""></p><blockquote><p>我們測試了 GNOME “<ruby>文件<rt>Files</rt></ruby>” v43 的開發版本，在這裏將向你深入披露其外觀、功能和性能的細節。</p></blockquote><p>GNOME <ruby>文件<rt>Files</rt></ruby>（以前的 Nautilus）也許是當今 GNOME 生態空間中使用最多的桌面應用。而且，自其首次發佈以來，它從未接受過什麼大修，而其他的 GNOME 應用乃至桌面本身都轉移到了一個較新的技術棧。</p><p>現在一切都變了。GNOME 開發者正在為整個桌面和 “文件” 採用 GTK4 和 libadwaita。</p>',5)),n("p",null,[t[1]||(t[1]=a("GNOME “文件” v43 將在 2022 年晚些時候與 GNOME 43 一起發佈，必將令人印象深刻。這個急需的 ",-1)),e(i,{href:"https://gitlab.gnome.org/GNOME/nautilus"},{default:o(()=>[...t[0]||(t[0]=[a("重製",-1)])]),_:1}),t[2]||(t[2]=a(" 帶來了原生的深色模式、很棒的 UI 以及出色的 libadwaita 觸控和 GTK4 性能提升。",-1))]),t[26]||(t[26]=p('<h3 id="gnome-文件-v43" tabindex="-1">GNOME “文件” v43 <a class="header-anchor" href="#gnome-文件-v43" aria-label="Permalink to “GNOME “文件” v43”">​</a></h3><p>我們安裝了 GNOME “文件” v43 的 Flatpak 開發版本，下面是我們的發現。</p><p>第一印象，你應該注意到漂亮的 UI 觸控，這要感謝 Libadwaita。關閉按鈕是漂亮的圓形，而地址欄、選擇高亮和整個文件窗口都有適當的間距和圓角。</p><p>所有的組件都沒有出現邊框高亮線。</p><p>下面是 v43（左）和 v42（右）的深淺模式的快速比較。</p><p><img src="https://www.debugpoint.com/wp-content/uploads/2022/03/GNOME-Files-43-and-42-Light-Mode-Comparison-1024x502.jpg" alt="GNOME Files 43 and 42 – Light Mode Comparison"></p><p><img src="https://www.debugpoint.com/wp-content/uploads/2022/03/GNOME-Files-43-and-42-Dark-Mode-Comparison-1024x493.jpg" alt="GNOME Files 43 and 42 – Dark Mode Comparison"></p><p>地址欄的文件夾分隔符保持不變。然而，字體卻有了些許潤色。地址欄的上下文菜單改變了，“<ruby>在終端打開<rt>Open in Terminal</rt></ruby>”選項沒有了。取而代之的是 “<ruby>在其它應用中打開<rt>Open in Other application</rt></ruby>” 菜單。引入了一個新的選項 “<ruby>創建鏈接<rt>Create Link</rt></ruby>”。我想許多用户會懷念 “在終端打開” 的選項。</p><blockquote><p>3/3 更新（感謝 Rashid）：“在終端打開” 選項是 Nautilus 擴展包的一部分。因此，Flatpak 構建版不能“看到”它。因此，它本身並沒有被刪除。</p></blockquote><p><img src="https://www.debugpoint.com/wp-content/uploads/2022/03/New-option-in-address-bar-menu-1024x267.jpg" alt="New option in address bar menu"></p><p>另一個重要的變化是你應該注意到兩個主工具條菜單：a）視圖按鈕和 b）漢堡主菜單。這些上下文菜單項顯示了菜單項及鍵盤快捷鍵。這也使它們看起來更顯眼一些。</p><p><img src="https://www.debugpoint.com/wp-content/uploads/2022/03/The-Hamburger-menu-now-have-keyboard-shortcuts-1024x331.jpg" alt="The Hamburger menu now have keyboard shortcuts"></p><p>文件夾的上下文菜單現在有一個向上的小箭頭，指向從它彈出的文件夾。文件夾的右鍵上下文菜單以組為單位組織得很好。例如，打開動作是分組的，而剪切、複製、粘貼在上下文菜單中以橫槓的形式明顯分開。</p><p><img src="https://www.debugpoint.com/wp-content/uploads/2022/03/Context-Menu-for-folder-changes-1024x560.jpg" alt="Context Menu for folder changes"></p><p>我還注意到一個新的選項 “<ruby>粘貼到該文件夾<rt>Paste into the folder</rt></ruby>”，這個很好。</p><p>Nautilus 搜索幾乎與 “文件” v42 相同，只是在 “文件” v43 中你可以通過創建日期/時間搜索。</p><p><s>然而，我注意到一個令人興奮的變化。上下文菜單中的文件關聯的應用名稱被刪除了。例如，如果你今天試圖在 “文件” v42 中打開一個文本文件，它在上下文菜單中顯示與之相關的應用名稱。在 “文件” v43 中，它只顯示 “打開”。我覺得這種改變是不必要的。之前的情況更好。</s></p><blockquote><p>3/3 更新（感謝 Rashid）：當我在試用 v43 的沙盒 Flatpak 版本時，它並沒有看到系統關聯。所以，這不是一個變化。但是，我又想知道，如果有人試圖真正使用 Flatpak 版本怎麼辦。</p></blockquote><p><img src="https://www.debugpoint.com/wp-content/uploads/2022/03/A-subtle-change-in-context-menu-for-file-association-1024x524.jpg" alt="A subtle change in context menu for file association"></p><p>所以，這就是我在這個應用的新 GTK4 版本中發現的整體變化。但它看起來不錯？不是嗎。此外，如果你是直接從 Ubuntu 20.04 LTS 來的，其中包含 “文件” 3.38，那麼也許你的體驗會是“哇”！如果你將 “文件” v43 與 “文件” v3.38 進行比較，大部分區域都發生了變化。對於這些用户來説，這將是一個相當不錯的體驗。</p><p>你應該記住，v43 仍在開發中，因此在未來最終發佈時，可能會發生變化。</p><h3 id="願望清單" tabindex="-1">願望清單 <a class="header-anchor" href="#願望清單" aria-label="Permalink to “願望清單”">​</a></h3><p>如果比較各種 Linux 文件管理器，其他的文件管理器的選項遠多於今天的 GNOME “文件”。</p><p>是這樣的。</p><p>例如，Nemo 或 Dolphin - 這兩個最好的文件管理器在各方面都勝過 “文件”。比較一下功能，GNOME “文件” 沒有一些流行的功能：</p><ul><li>雙面板或分割視圖</li><li>從上下文菜單中打開一個根文件夾是困難的</li><li>一個用於文件夾瀏覽的向上箭頭</li><li>沒有從上下文菜單中創建一個新文件（文本、電子表格等）的選項</li><li>更多的排序和搜索功能</li></ul><p>我們希望這些功能能儘快出現在 GNOME “文件” 中。</p><h3 id="何時能用" tabindex="-1">何時能用 <a class="header-anchor" href="#何時能用" aria-label="Permalink to “何時能用”">​</a></h3><p>如上所述，這個版本的 GNOME “文件” 將與 GNOME 43 一起提供。因此，從 Linux 發行計劃的角度來看，你應該在 2022 年 10 月的 Ubuntu 22.10 和今年晚些時候的 Fedora 37 上擁有它。</p>',29)),n("p",null,[t[6]||(t[6]=a("不幸的是，",-1)),e(i,{href:"https://www.debugpoint.com/2022/01/ubuntu-22-04-lts/"},{default:o(()=>[...t[3]||(t[3]=[a("Ubuntu 22.04 LTS",-1)])]),_:1}),t[7]||(t[7]=a("（Jammy Jellyfish）和帶有 ",-1)),e(i,{href:"https://www.debugpoint.com/2021/12/gnome-42/"},{default:o(()=>[...t[4]||(t[4]=[a("GNOME 42",-1)])]),_:1}),t[8]||(t[8]=a(" 的 ",-1)),e(i,{href:"https://www.debugpoint.com/2022/02/fedora-36/"},{default:o(()=>[...t[5]||(t[5]=[a("Fedora 36",-1)])]),_:1}),t[9]||(t[9]=a(" 將不會有 GNOME “文件” 43。主要原因是時間表不匹配，而且它是要移植到 GTK4 和徹底測試的複雜應用之一。然而，大部分上述的內部功能仍然會在 “文件” 42 中。但它可能缺少漂亮的 UI 變化和主題。",-1))]),t[27]||(t[27]=n("p",null,"儘管如此，我相信這個流行的文件管理器看起來不錯，當它發佈時，用户應該會很興奮地使用它。讓我知道你對 GNOME “文件” 43 的新變化的看法，請在下面的評論框中留言。",-1)),t[28]||(t[28]=n("p",null,"加油！",-1)),t[29]||(t[29]=n("hr",null,null,-1)),n("p",null,[t[11]||(t[11]=a("via: ",-1)),e(i,{href:"https://www.debugpoint.com/2022/03/gnome-files-43/"},{default:o(()=>[...t[10]||(t[10]=[a("https://www.debugpoint.com/2022/03/gnome-files-43/",-1)])]),_:1})]),n("p",null,[t[16]||(t[16]=a("作者：",-1)),e(i,{href:"https://www.debugpoint.com/author/admin1/"},{default:o(()=>[...t[12]||(t[12]=[a("Arindam",-1)])]),_:1}),t[17]||(t[17]=a(" 選題：",-1)),e(i,{href:"https://github.com/lujun9972"},{default:o(()=>[...t[13]||(t[13]=[a("lujun9972",-1)])]),_:1}),t[18]||(t[18]=a(" 譯者：",-1)),e(i,{href:"https://github.com/geekpi"},{default:o(()=>[...t[14]||(t[14]=[a("geekpi",-1)])]),_:1}),t[19]||(t[19]=a(" 校對：",-1)),e(i,{href:"https://github.com/wxy"},{default:o(()=>[...t[15]||(t[15]=[a("wxy",-1)])]),_:1})]),n("p",null,[t[22]||(t[22]=a("本文由 ",-1)),e(i,{href:"https://github.com/LCTT/TranslateProject"},{default:o(()=>[...t[20]||(t[20]=[a("LCTT",-1)])]),_:1}),t[23]||(t[23]=a(" 原創編譯，",-1)),e(i,{href:"https://linux.cn/"},{default:o(()=>[...t[21]||(t[21]=[a("Linux中國",-1)])]),_:1}),t[24]||(t[24]=a(" 榮譽推出",-1))])])}const O=l(d,[["render",m]]);export{M as __pageData,O as default};
